-- Phase 3 completion: durable crew snapshots and scoped Keepsake consent.
CREATE TABLE `PlayerChronicleParticipantSnapshot` (`id` VARCHAR(191) NOT NULL, `historyRecordId` VARCHAR(191) NOT NULL, `sourceMembershipId` VARCHAR(191) NOT NULL, `participantProfileId` VARCHAR(191) NULL, `displayNameSnapshot` VARCHAR(191) NOT NULL, `avatarAltSnapshot` VARCHAR(191) NULL, `participationRole` VARCHAR(191) NOT NULL, `crewRoleSnapshot` VARCHAR(191) NULL, `joinedAt` DATETIME(3) NULL, `completedAt` DATETIME(3) NULL, `removedAt` DATETIME(3) NULL, `projectionEligibility` VARCHAR(191) NOT NULL DEFAULT 'ONLY_ME', `tombstoneState` VARCHAR(191) NOT NULL DEFAULT 'ACTIVE', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `PCParticipantSnapshot_history_source_key` (`historyRecordId`,`sourceMembershipId`), KEY `PCParticipantSnapshot_history_eligibility_idx` (`historyRecordId`,`projectionEligibility`), CONSTRAINT `PlayerChronicleParticipantSnapshot_historyRecordId_fkey` FOREIGN KEY (`historyRecordId`) REFERENCES `PlayerChronicleRecord`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `VoyageKeepsakeConsent` DROP INDEX `VoyageKeepsakeConsent_keepsakeId_participantId_key`, ADD COLUMN `scope` VARCHAR(191) NOT NULL DEFAULT 'GENERAL_MEDIA', ADD COLUMN `state` VARCHAR(191) NOT NULL DEFAULT 'PENDING', ADD COLUMN `historicalLabel` VARCHAR(191) NULL, ADD COLUMN `requestedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), ADD COLUMN `decidedAt` DATETIME(3) NULL, ADD COLUMN `requestedByProfileId` VARCHAR(191) NULL, ADD COLUMN `correlationId` VARCHAR(191) NULL, ADD UNIQUE INDEX `VoyageKeepsakeConsent_keepsakeId_participantId_scope_key` (`keepsakeId`,`participantId`,`scope`), ADD INDEX `VoyageKeepsakeConsent_participantId_state_idx` (`participantId`,`state`);
UPDATE `VoyageKeepsakeConsent` SET `state` = CASE WHEN `granted` THEN 'GRANTED' WHEN `revokedAt` IS NOT NULL THEN 'REVOKED' ELSE 'PENDING' END, `decidedAt` = CASE WHEN `granted` OR `revokedAt` IS NOT NULL THEN `updatedAt` ELSE NULL END;
ALTER TABLE `VoyageKeepsakeConsent` DROP COLUMN `granted`;
